import{_ as d,o as e,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Test — FR 3.6.1 / DA-978","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-1-identify-task-detail/test.md","filePath":"feature/content-task-workflow/3-6-1-identify-task-detail/test.md"}'),i={name:"feature/content-task-workflow/3-6-1-identify-task-detail/test.md"};function r(h,t,s,c,o,g){return e(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="test-—-fr-3-6-1-da-978" tabindex="-1">Test — FR 3.6.1 / DA-978 <a class="header-anchor" href="#test-—-fr-3-6-1-da-978" aria-label="Permalink to &quot;Test — FR 3.6.1 / DA-978&quot;">​</a></h1><p>&gt; <strong>Ưu tiên BA mới 2026-10-15:</strong> xem <a href="./../task-five-state-inline-edit/spec.html">Task năm trạng thái + inline autosave</a>. TODO thay BACKLOG/DETAIL_IDENTIFIED/ASSIGNED; giao việc cần mô tả + deadline hợp lệ, không chuyển trạng thái. IN_REVIEW lưu bước QC/Manager/Client riêng, reject về IN_PROGRESS, bước cuối thành công mới FINISHED. Manager khóa sửa/giao lại sau lần bắt đầu đầu tiên. Phần vòng đời/form cũ bên dưới được giữ làm lịch sử, không phải contract mới. Đợt này chỉ code FR 3.6.1/2; Approval và Comments không được coi là đã hoàn thành.</p><h2 id="bang-chi-tiet-ben-phai-—-kich-ban-truoc-code-2026-10-15" tabindex="-1">Bảng chi tiết bên phải — kịch bản trước code 2026-10-15 <a class="header-anchor" href="#bang-chi-tiet-ben-phai-—-kich-ban-truoc-code-2026-10-15" aria-label="Permalink to &quot;Bảng chi tiết bên phải — kịch bản trước code 2026-10-15&quot;">​</a></h2><ul><li>P01: click/Enter Task mở đúng workflow ở bên phải, list vẫn tương tác trên desktop, không dialog tóm tắt hoặc chuyển trang; URL có task.</li><li>P02: đóng bằng nút/Escape, trả focus về nút Task; Back/Forward mở/đóng/chọn đúng Task, giữ query khác/filter/view/page.</li><li>P03: mở Task A rồi B hoặc đổi Workspace: không rò dữ liệu/bản nháp; provider không thiếu, không tạo client mỗi rerender.</li><li>P04: direct link task và route detail cũ mở cùng bảng; không phụ thuộc Task có trên trang list hiện tại.</li><li>P05: lưu brief/giao việc/bắt đầu thành công cập nhật status/assignee/deadline trong list; không tự start khi mở; 409 giữ draft.</li><li>P06: loading/error/retry, schema/legacy locked, Client chỉ xem; không mock fallback hoặc mở quyền mới.</li><li>P07: 375/768/1440, light/dark/vi/en, không tràn viewport; mobile Sheet có focus trap và Escape/close; desktop không trap focus danh sách.</li></ul><p>Kết quả 2026-10-15: 132 Vitest tests/14 files pass (4 regression provider/desktop aside/legacy route dùng workflow hook thật), TypeScript và production build pass. Scoped lint không lỗi; useTasks vẫn có 2 cảnh báo hook từ trước. Browser CLI dùng TaskList thật + workflow thật + MemoryRouter, không bọc QueryClientProvider từ harness, mock API không ghi DB: desktop không modal, giữ query/search/view, chuyển Task không lẫn draft, Back/Forward, detail/assign/start cập nhật list, Creator mở bảng không tự start, 409 giữ draft, Escape/focus/Enter, Client readonly, direct/legacy links, error/retry; light/dark, vi/en, 375/768/1440. Không có pageerror; Vite HMR bị local-network policy chặn và HTTP 409/503 chủ ý từ fixture không phải lỗi ứng dụng. Browser không chứng minh live Atlas/auth/ACL; page/filter/pagination chưa test với dataset nhiều trang. Ảnh và harness ở <code>.local-backups/task-panel-20261015</code> ngoài repo Web; không thêm Playwright test spec.</p><p>Baseline giai đoạn 1 chưa test ứng dụng; các dòng bên dưới giữ checklist nghiệm thu đầy đủ. Đợt 2026-10-15 đã có unit/MockMvc, Mongo cô lập và browser mock cho phần workflow; evidence/giới hạn ở <a href="./../task-workflow-phase-2-3.html">bàn giao đợt 2/3</a>. Không coi tất cả dòng đã pass trên Atlas.</p><table tabindex="0"><thead><tr><th>ID</th><th>Input/điều kiện</th><th>AC</th><th>Mong đợi</th><th>Loại</th><th>Trạng thái</th></tr></thead><tbody><tr><td>D01</td><td>Manager, BACKLOG, brief + deadline hợp lệ</td><td>Xác định lần đầu</td><td>DETAIL_IDENTIFIED, giữ Task ID/nguồn</td><td>Happy</td><td>Chưa test</td></tr><tr><td>D02</td><td>POST có dueDate và plannedPublishAt ≥ dueDate</td><td>Hai thời điểm</td><td>Lưu riêng, không tạo lịch publish</td><td>Happy</td><td>Chưa test</td></tr><tr><td>D03</td><td>LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION</td><td>Khung 5 loại</td><td>Lưu common brief, không đổi specialist content</td><td>Happy</td><td>Chưa test</td></tr><tr><td>D04</td><td>DETAIL_IDENTIFIED/ASSIGNED chưa bắt đầu, revision đúng</td><td>Sửa trước start</td><td>Giữ status và người phụ trách</td><td>Edge</td><td>Chưa test</td></tr><tr><td>D05</td><td>IN_PROGRESS/review/terminal hoặc reject → ASSIGNED có marker</td><td>Khóa sau start</td><td>409, không sửa/hồi sinh Task</td><td>Error</td><td>Chưa test</td></tr><tr><td>D06</td><td>Creator/Client/Owner không là Manager WS</td><td>Quyền Manager</td><td>403, không ghi</td><td>Error</td><td>Chưa test</td></tr><tr><td>D07</td><td>Task thuộc WS khác; người dùng không còn active cùng WS</td><td>Workspace scope</td><td>Không lộ dữ liệu, 404/403 theo auth scope</td><td>Error</td><td>Chưa test</td></tr><tr><td>D08</td><td>DueDate trước max(today,start), sau end; timezone sát nửa đêm</td><td>Giới hạn ngày</td><td>UI min/max và API cùng từ chối</td><td>Error</td><td>Chưa test</td></tr><tr><td>D09</td><td>POST publish trước due hoặc ngoài Campaign; non-POST gửi publish</td><td>Hai thời điểm/ngày</td><td>Field errors, không tự clamp</td><td>Error</td><td>Chưa test</td></tr><tr><td>D10</td><td>Manual không Campaign; hạn hôm nay</td><td>Hạn manual</td><td>Hợp lệ theo ngày Workspace</td><td>Edge</td><td>Chưa test</td></tr><tr><td>D11</td><td>Campaign hết ngày hoặc completed</td><td>Edge case spec §7</td><td>Không có hạn mới hợp lệ/409 completed</td><td>Edge</td><td>Chưa test</td></tr><tr><td>D12</td><td>Content Request đã có description</td><td>Edge case spec §7</td><td>Có thể giữ/bổ sung, không mất sourceRefId</td><td>Edge</td><td>Chưa test</td></tr><tr><td>D13</td><td>Revision stale/detail đua cancel hoặc completion</td><td>Giữ audit/state</td><td>Conflict, CANCELLED không bị phục hồi</td><td>Error</td><td>Chưa test</td></tr><tr><td>D14</td><td>Legacy thiếu first-start/revision</td><td>Q13/legacy</td><td>Client vẫn đọc/bình luận; Manager cần review trước mutation</td><td>Edge</td><td>Chưa test</td></tr><tr><td>D15</td><td>Client xem Task Manager tạo thủ công và Task Campaign/Request</td><td>Q13</td><td>Đọc workflow cùng WS, không có bộ chọn nội bộ/thường</td><td>Happy</td><td>Chưa test</td></tr><tr><td>D16</td><td>Mở editor/trang mà không bấm start</td><td>Trigger start</td><td>Không có firstStartedAt/status mới</td><td>Edge</td><td>Chưa test</td></tr><tr><td>D17</td><td>Đổi vi/en; light/dark; 375/768/1440; chỉ bàn phím</td><td>i18n/theme § cuối</td><td>Không hardcode, không mất contrast; focus lỗi và giữ input</td><td>Happy</td><td>Chưa test</td></tr><tr><td>D18</td><td>DB chưa có foundation</td><td>Error/readiness</td><td>503 rõ, không mutation nửa chừng</td><td>Error</td><td>Chưa test</td></tr><tr><td>D19</td><td>Client đọc được Task rồi gọi PATCH detail/assign</td><td>Q13/quyền</td><td>403, quyền đọc/bình luận không cấp quyền quản lý</td><td>Error</td><td>Chưa test</td></tr><tr><td>D20</td><td>Detail đua assign cùng expectedRevision</td><td>CAS</td><td>Mutation stale trả 409, không ghi đè cấu hình giao việc</td><td>Edge</td><td>Chưa test</td></tr></tbody></table><p>Schema tests/evidence tập trung tại <a href="./../task-workflow-phase-1.html">setup giai đoạn 1</a>, không thay test API này.</p><p>Slice bổ sung: mọi nguồn vào đúng Task Detail; read workflow không cấp quyền editor; min/max ngày và timezone khác browser; giờ DST thiếu/không rõ; legacy raw marker missing khác explicit null; không tạo/sửa DB khi chỉ mở trang.</p>',9)])])}const p=d(i,[["render",r]]);export{k as __pageData,p as default};
